/// Returns an index of a minimum element in the half-open subarray [s, e).
/// Preconditions (assumed true as per problem statement):
/// - a.len() > 0
/// - 0 <= s < e <= a.len()
pub fn find_min_index(a: &[i32], s: usize, e: usize) -> usize {
    // Initialize with the first element in the range (range is non-empty).
    let mut min_i = s;
    let mut min_val = a[s];

    for i in (s + 1)..e {
        let v = a[i];
        if v < min_val {
            min_val = v;
            min_i = i;
        }
    }

    min_i
}

